import { ExpenseStatus, type Expense } from "../../types/work-costs"
import { TimeEntryStatus, type ClientInvoice, type TimeEntry } from "../../types/work-billing"
import { LeaveStatus, type LeaveRequest } from "../../types/work-planning"
import { type ProjectPage, type TaskComment, type WorkProject, type WorkTask, isClosedStatus } from "../../types/work-projects"
import type { SatisfactionResponse } from "../../types/work-feedback"
import type { ClientFollowUp, ClientNote } from "../../types/work-crm"
import { lowRatingsFor } from "./satisfaction"
import type { EmployeeDocument } from "../../types/work-hr"
import type { PerformanceReview } from "../../types/work-reviews"
import { EmployeeStatus, type Client, type Employee } from "../../types/workforce"
import { addDays, displayStatus } from "./billing"
import { isStale } from "./deals"
import { actionItems } from "./project-pages"
import { billTotals } from "./supplier-bills"
import type { Deal, PipelineSettings } from "../../types/work-sales"
import { QuoteStatus, type Quote } from "../../types/work-quotes"
import { SupplierBillStatus, type SupplierBill } from "../../types/work-purchases"
import { isOnTask } from "./task-extras"
import { waitingRequests } from "./client-requests"
import type { ClientRequest } from "../../types/work-requests"
import { documentsNeedingAction } from "./documents"
import { reviewAction, type ReviewViewer } from "./reviews"

export type InboxCategory = "team" | "billing" | "security" | "system"

/** Something the signed-in person should act on, with where to do it. */
export interface InboxItem {
  /** Changes when the content changes, so a new item shows as unread again */
  id: string
  category: InboxCategory
  /** Translation key and values for the title and message */
  title: string
  message: string
  values: Record<string, string | number>
  href: string
}

export interface InboxInput {
  viewer: ReviewViewer
  rights: { approveTime: boolean; invoices: boolean; hr: boolean; projects?: boolean; purchases?: boolean }
  employees: Employee[]
  reviews: PerformanceReview[]
  entries: TimeEntry[]
  leave: LeaveRequest[]
  expenses: Expense[]
  invoices: ClientInvoice[]
  documents: EmployeeDocument[]
  tasks: WorkTask[]
  /** Client answers and projects, for low ratings (Phase 6h.2) */
  feedback?: SatisfactionResponse[]
  projects?: WorkProject[]
  /** Client follow-ups (CRM step 5) */
  followUps?: ClientFollowUp[]
  /** Client notes, for @mentions of the person in the last 14 days (CRM step 10) */
  clientNotes?: ClientNote[]
  clients?: Client[]
  /** Task comments that @mention the person lately (newest first) */
  taskMentions?: TaskComment[]
  /** Client requests waiting for an answer, for people who manage projects (P3) */
  requests?: ClientRequest[]
  /** Deals the person owns that stopped moving (A4.2) */
  deals?: Deal[]
  pipeline?: PipelineSettings
  /** Sent quotes about to expire, for people who see invoices (A4.2) */
  quotes?: Quote[]
  /** Approved supplier bills coming due, for people who enter purchases (A4.2) */
  supplierBills?: SupplierBill[]
  /** Meeting notes whose open action items @mention the person (A4.2) */
  projectPages?: ProjectPage[]
  today: string
}

/**
 * The work inbox behind the bell: reviews waiting for the person, approvals
 * waiting for approvers, overdue invoices for finance, expiring documents for
 * HR and the person's own overdue tasks. Approvers never see their own items.
 */
export function buildInbox(d: InboxInput): InboxItem[] {
  const me = d.viewer.employeeId
  const name = (id: string) => d.employees.find((e) => e.id === id)?.name ?? "—"
  const items: InboxItem[] = []

  for (const r of d.reviews) {
    const action = reviewAction(r, d.viewer)
    if (!action) continue
    items.push({
      id: `review:${r.id}:${action}`,
      category: "team",
      title: `inboxReview_${action}`,
      message: "inboxReviewMessage",
      values: { name: name(r.employeeId), period: r.period },
      href: "/dashboard/reviews",
    })
  }

  if (d.rights.approveTime) {
    const mine = (by?: string) => !!by && by === (me ?? (d.viewer.isAdmin ? "admin" : ""))
    const sheets = d.entries.filter((e) => e.status === TimeEntryStatus.SUBMITTED && e.employeeId !== me && !mine(e.firstApprovedBy))
    const people = new Set(sheets.map((e) => e.employeeId)).size
    if (sheets.length) items.push({ id: `time:${sheets.length}`, category: "team", title: "inboxTimesheets", message: "inboxTimesheetsMessage", values: { count: people, hours: sheets.reduce((s, e) => s + e.hours, 0) }, href: "/dashboard/time-approvals" })
    const leave = d.leave.filter((l) => l.status === LeaveStatus.PENDING && l.employeeId !== me && !mine(l.firstApprovedBy))
    if (leave.length) items.push({ id: `leave:${leave.map((l) => l.id).join(",")}`, category: "team", title: "inboxLeave", message: "inboxLeaveMessage", values: { count: leave.length }, href: "/dashboard/leave" })
    const expenses = d.expenses.filter((x) => x.status === ExpenseStatus.SUBMITTED && x.employeeId !== me && !mine(x.firstApprovedBy))
    if (expenses.length) items.push({ id: `expenses:${expenses.map((x) => x.id).join(",")}`, category: "billing", title: "inboxExpenses", message: "inboxExpensesMessage", values: { count: expenses.length }, href: "/dashboard/expenses" })
  }

  if (d.rights.invoices) {
    const overdue = d.invoices.filter((i) => displayStatus(i, d.today, d.invoices) === "overdue")
    if (overdue.length) items.push({ id: `overdue:${overdue.map((i) => i.id).join(",")}`, category: "billing", title: "inboxOverdue", message: "inboxOverdueMessage", values: { count: overdue.length }, href: "/dashboard/receivables" })
  }

  if (d.rights.hr) {
    const staff = d.employees.filter((e) => e.status !== EmployeeStatus.INACTIVE).map((e) => e.id)
    const docs = documentsNeedingAction(d.documents, staff, d.today)
    if (docs.length) items.push({ id: `docs:${docs.map((x) => `${x.doc.id}-${x.status}`).join(",")}`, category: "security", title: "inboxDocuments", message: "inboxDocumentsMessage", values: { count: docs.length }, href: "/dashboard/documents" })
  }

  const low = lowRatingsFor(d.feedback ?? [], d.projects ?? [], d.viewer)
  if (low.length) {
    const first = d.projects?.find((p) => p.id === low[0]!.projectId)
    items.push({ id: `csat:${low.map((r) => r.id).join(",")}`, category: "team", title: "inboxLowRating", message: "inboxLowRatingMessage", values: { count: low.length, project: first?.name ?? "" }, href: first ? `/dashboard/projects/${first.id}` : "/dashboard/projects" })
  }

  if (me) {
    const late = d.tasks.filter((t) => isOnTask(t, me) && !isClosedStatus(t.status) && t.dueDate && t.dueDate < d.today)
    if (late.length) items.push({ id: `tasks:${late.map((t) => t.id).join(",")}`, category: "system", title: "inboxTasks", message: "inboxTasksMessage", values: { count: late.length }, href: "/dashboard/my-work" })
    // tasks the person watches without working on them (P1)
    const watched = d.tasks.filter((t) => t.watcherIds?.includes(me) && !isOnTask(t, me) && !isClosedStatus(t.status) && t.dueDate && t.dueDate < d.today)
    if (watched.length) {
      const first = watched[0]!
      items.push({ id: `watched:${watched.map((t) => `${t.id}-${t.dueDate}`).join(",")}`, category: "team", title: "inboxWatched", message: "inboxWatchedMessage", values: { count: watched.length, task: first.title }, href: `/dashboard/projects/${first.projectId}?task=${first.id}` })
    }
    const due = (d.followUps ?? []).filter((f) => f.ownerId === me && !f.doneAt && f.dueDate <= d.today)
    if (due.length) {
      const lateCount = due.filter((f) => f.dueDate < d.today).length
      items.push({ id: `follow-ups:${due.map((f) => `${f.id}-${f.dueDate}`).join(",")}`, category: "team", title: "inboxFollowUps", message: lateCount ? "inboxFollowUpsLate" : "inboxFollowUpsToday", values: { count: due.length, late: lateCount }, href: "/dashboard/my-work" })
    }
    // someone named the person in a client note lately (CRM step 10); one item per note
    const since = new Date(Date.parse(`${d.today}T00:00:00Z`) - 14 * 86_400_000).toISOString().slice(0, 10)
    for (const n of d.clientNotes ?? []) {
      if (!n.mentionIds?.includes(me) || n.authorId === me || n.date < since) continue
      const client = d.clients?.find((c) => c.id === n.clientId)
      if (!client) continue
      items.push({ id: `mention:${n.id}`, category: "team", title: "inboxMention", message: "inboxMentionMessage", values: { name: n.authorId ? name(n.authorId) : "—", client: client.name }, href: `/dashboard/clients/${client.id}?tab=activity` })
    }
    // someone named the person in a task comment lately; one item per comment
    const myName = d.employees.find((e) => e.id === me)?.name
    for (const c of d.taskMentions ?? []) {
      if (!c.mentionIds?.includes(me) || c.authorName === myName || c.createdAt.slice(0, 10) < since) continue
      const task = d.tasks.find((x) => x.id === c.taskId)
      if (!task || task.deletedAt) continue
      items.push({ id: `task-mention:${c.id}`, category: "team", title: "inboxTaskMention", message: "inboxTaskMentionMessage", values: { name: c.authorName, task: task.title }, href: `/dashboard/projects/${task.projectId}?task=${task.id}` })
    }
  }
  if (d.rights.projects) {
    const waiting = waitingRequests(d.requests ?? [], d.today)
    if (waiting.length) {
      const urgent = waiting.filter((r) => r.urgent).length
      items.push({ id: `requests:${waiting.map((r) => r.id).join(",")}`, category: "team", title: "inboxRequests", message: urgent ? "inboxRequestsUrgent" : "inboxRequestsMessage", values: { count: waiting.length, urgent }, href: "/dashboard/requests" })
    }
  }
  if (me) {
    const stale = (d.deals ?? []).filter((x) => x.ownerId === me && isStale(x, d.today, d.pipeline))
    if (stale.length) items.push({ id: `stale-deals:${stale.map((x) => `${x.id}-${x.stageSince ?? ""}`).join(",")}`, category: "team", title: "inboxStaleDeals", message: "inboxStaleDealsMessage", values: { count: stale.length, deal: stale[0]!.title }, href: "/dashboard/deals" })
  }
  if (d.rights.invoices) {
    const soon = addDays(d.today, 3)
    const expiring = (d.quotes ?? []).filter((q) => q.status === QuoteStatus.SENT && q.validUntil >= d.today && q.validUntil <= soon)
    if (expiring.length) items.push({ id: `quotes-expiring:${expiring.map((q) => `${q.id}-${q.validUntil}`).join(",")}`, category: "billing", title: "inboxQuotesExpiring", message: "inboxQuotesExpiringMessage", values: { count: expiring.length }, href: "/dashboard/quotes" })
  }
  if (d.rights.purchases) {
    const soon = addDays(d.today, 7)
    const due = (d.supplierBills ?? []).filter((b) => b.status === SupplierBillStatus.APPROVED && b.dueDate >= d.today && b.dueDate <= soon && billTotals(b).balance > 0)
    if (due.length) items.push({ id: `bills-due:${due.map((b) => `${b.id}-${b.dueDate}`).join(",")}`, category: "billing", title: "inboxBillsDue", message: "inboxBillsDueMessage", values: { count: due.length }, href: "/dashboard/supplier-bills" })
  }
  if (me) {
    // an open action item that @mentions the person by full name, not yet turned into a task
    const mention = `@${name(me)}`.toLowerCase()
    const mine = (d.projectPages ?? []).flatMap((pg) => actionItems(pg.body).filter((a) => !a.done && !a.key && a.text.toLowerCase().includes(mention)).map((a) => ({ pg, a })))
    if (mine.length) {
      const first = mine[0]!
      items.push({ id: `actions:${mine.map((m) => `${m.pg.id}-${m.a.line}`).join(",")}`, category: "team", title: "inboxActionItems", message: "inboxActionItemsMessage", values: { count: mine.length, page: first.pg.title }, href: `/dashboard/projects/${first.pg.projectId}?tab=pages` })
    }
  }
  return items
}
